from datetime import date, datetime, timedelta

import requests

import config
import database
import models


def _get_json(path, params=None):
    """Attempt one bounded GET, returning None for transport, status or JSON failures."""
    try:
        # Course: A06 – query parameters are encoded by requests, never interpolated into SQL.
        with requests.get(config.API_BASE_URL + path, params=params,
                           timeout=config.API_TIMEOUT_SECONDS, allow_redirects=False) as response:
            if response.status_code == 200:
                return response.json()
    except (requests.RequestException, ValueError):
        return None
    return None


def _post_json(body):
    """Attempt one bounded POST; a lost response is resolved against shared local storage."""
    try:
        with requests.post(config.API_BASE_URL + '/interactions', json=body,
                            timeout=config.API_TIMEOUT_SECONDS, allow_redirects=False) as response:
            if response.status_code == 201:
                return response.json()
    except (requests.RequestException, ValueError):
        return None
    return None


def is_api_available():
    """Check health/version; the UI owns the 30-second cache."""
    return _get_json('/health') == {'status': 'ok', 'version': config.APP_VERSION}


def _local_interval(start, end):
    """Accept naive Zurich datetimes or dates and retain exact half-open time boundaries."""
    values = []
    for value in (start, end):
        if isinstance(value, date) and not isinstance(value, datetime):
            value = datetime.combine(value, datetime.min.time())
        if not isinstance(value, datetime) or value.tzinfo is not None:
            raise ValueError('Event boundaries must be dates or naive Zurich datetimes.')
        values.append(value)
    if values[1] <= values[0]:
        raise ValueError('The event range must end after it starts.')
    return values


def _event_from_json(row):
    """Reject malformed rows, including fractional money, before constructing a domain event."""
    if not isinstance(row, dict) or set(row) != set(config.EVENT_RECORD_FIELDS):
        raise ValueError('API event fields do not match the local row format.')
    for field in config.API_INTEGER_FIELDS:
        value = row[field]
        if value is None and field in config.API_NULLABLE_INTEGERS:
            continue
        if type(value) is not int:
            raise ValueError('API identifiers, flags and Rappen must be integers.')
    return models.event_from_row(row)


def _database_events(start, end, connection):
    """Read equivalent domain events locally, closing only a connection owned by this call."""
    owned = connection is None
    connection = connection if connection is not None else database.get_connection()
    try:
        frame = database.get_events_df(connection, start, end)
        events = [models.event_from_row(row) for row in frame.reset_index().to_dict('records')]
        return events, 'database'
    finally:
        if owned:
            connection.close()


def get_events(start, end, available=True, connection=None):
    """Return (events, origin), falling back after at most one failed HTTP request.

    :param start: inclusive date or naive local datetime
    :param end: exclusive date or naive local datetime
    :param available: UI's cached health result; false skips HTTP entirely
    :param connection: optional existing connection for the database fallback
    :return: Event objects and either 'api' or 'database'
    """
    start, end = _local_interval(start, end)
    if available:
        query_end = end.date()
        if end.time() != datetime.min.time():
            query_end += timedelta(days=1)
        rows = _get_json('/events', {'from': start.date().isoformat(), 'to': query_end.isoformat()})
        if isinstance(rows, list):
            try:
                events = [_event_from_json(row) for row in rows]
                return [event for event in events if start <= event.start < end], 'api'
            except (ValueError, TypeError, KeyError, OverflowError):
                pass
    return _database_events(start, end, connection)


def get_event(event_id, available=True, connection=None):
    """Return (Event or None, origin) for details, with the same row format on both paths."""
    if type(event_id) is not int or not 1 <= event_id <= config.API_MAX_ID:
        raise ValueError('Event ID must be a positive integer.')
    if available:
        row = _get_json(f'/events/{event_id}')
        try:
            event = _event_from_json(row)
            if event.event_id == event_id:
                return event, 'api'
        except (ValueError, TypeError, KeyError, OverflowError):
            pass
    owned = connection is None
    connection = connection if connection is not None else database.get_connection()
    try:
        row = database.get_event_row(connection, event_id)
        return (models.event_from_row(row) if row is not None else None), 'database'
    finally:
        if owned:
            connection.close()


def _matches_action(row, user_id, event_id, action, rating):
    """Recognize a complete stored result for exactly the requested user, event and action."""
    fields = {'id', 'user_id', 'event_id', 'status', 'rating',
              'confirmed_at', 'answered_at', 'is_demo'}
    if not isinstance(row, dict) or not fields.issubset(row):
        return False
    if row['user_id'] != user_id or row['event_id'] != event_id:
        return False
    if row['status'] != config.INTERACTION_TARGETS[action]:
        return False
    return action != 'rate' or row['rating'] == rating


def _fallback_interaction(connection, previous, user_id, event_id, action, rating, now):
    """Recover a committed write after a lost response, or apply the normal local transition."""
    current = database.get_interaction(connection, user_id, event_id)
    # The API shares this DB. A changed row matching the requested state proves the result exists.
    # An unchanged duplicate confirmation still goes through validation and remains an error.
    if current != previous and _matches_action(current, user_id, event_id, action, rating):
        return current
    return database.save_interaction(connection, user_id, event_id, action, rating, now)


def save_interaction(user_id, event_id, action, rating=None, available=True,
                      connection=None, now=None):
    """Return (stored interaction, origin) using one HTTP attempt or the shared state machine.

    :param user_id: interaction owner
    :param event_id: occurrence ID
    :param action: confirm, cancel, attended, not_attended or rate
    :param rating: 1–5 for rate; None otherwise
    :param available: cached health hint; a stale positive still falls back immediately on failure
    :param connection: optional shared local connection, never closed by this function
    :param now: injected clock for the direct fallback; HTTP always uses the server's clock
    :return: stored interaction and either 'api' or 'database'
    """
    database.validate_interaction_input(user_id, event_id, action, rating)
    owned = connection is None
    connection = connection if connection is not None else database.get_connection()
    try:
        previous = database.get_interaction(connection, user_id, event_id)
        if available:
            body = {'user_id': user_id, 'event_id': event_id, 'action': action, 'rating': rating}
            result = _post_json(body)
            if _matches_action(result, user_id, event_id, action, rating):
                return result, 'api'
        result = _fallback_interaction(connection, previous, user_id, event_id, action, rating, now)
        return result, 'database'
    finally:
        if owned:
            connection.close()
